                var indices = new List<uint>();
                for (int j = 0; j < 32; j++)
                    for (int i = 0; i < 32; i++)
                    {
                        var key = new SandDeformation.Key((int)floor((double)(@base.x + i * 2) / 4), (int)floor((double)(@base.z + j * 2) / 4));
                        if (holes.Contains(key)) continue;
