using System;
using System.IO;
using System.Threading.Tasks;
using Godot;
namespace Marvin;
public static class Review2154 {
 [GameMode("--review-2154-cache")]
 public static async Task Cache(string dir, SceneTree tree) {
  Directory.CreateDirectory(dir);
  var material = new SCNMaterial();
  var weak = new System.Collections.Generic.List<WeakReference>();
  var field = typeof(MaterialGpu).GetField("variants", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
  var results = new System.Collections.Generic.List<string>();
  for (int round = 0; round < 3; round++) {
   for (int i = 0; i < 64; i++) AddVariant(material, weak);
   await AppController.frame(tree);
   GC.Collect(); GC.WaitForPendingFinalizers(); GC.Collect();
   var cache = (System.Collections.IDictionary)field.GetValue(material.gpu);
   int alive=0; foreach(var w in weak) if(w.IsAlive) alive++;
   string result=$"created={(round+1)*64} materialVariants={cache.Count} geometriesAlive={alive}";
   GD.Print(result); results.Add(result);
  }
  File.WriteAllLines(Path.Combine(dir,"cache-state.txt"),results);
  SceneKit.Foundation.exit(0);
 }
 [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
 private static void AddVariant(SCNMaterial material, System.Collections.Generic.List<WeakReference> weak) {
  var geometry = new SCNPlane(4,4);
  geometry.materials = new() { material };
  geometry.shaderModifiers = new() { [SCNShaderModifierEntryPoint.geometry] = "#pragma arguments\nsampler2D duneHeights;\n#pragma body\nVERTEX.y += texture(duneHeights, vec2(0.5)).r;" };
  var heights = new SCNMaterialProperty();
  var device = MTLCreateSystemDefaultDevice();
  var descriptor = MTLTextureDescriptor.texture2DDescriptor(pixelFormat: MTLPixelFormat.r32Float,width:67,height:67,mipmapped:false);
  heights.contents = device.makeTexture(descriptor);
  geometry.setValue(heights,"duneHeights");
  material.gpu.Variant(geometry,0,ShaderComposer.VariantFlags.None);
  weak.Add(new WeakReference(geometry));
 }
 [GameMode("--review-2154")]
 public static async Task Run(string dir, SceneTree tree) {
  var app=await AppController.launchSmoke(tree, dir);
  app.loadDirtTrack();
  bool sampled=false;
  var end=Time.GetTicksMsec()+90000;
  while(app.isLoadingDirt && Time.GetTicksMsec()<end) {
   if(!sampled && app.loadingView.history.Count>0 && app.loadingView.history[^1]>=0.93) {
    sampled=true;
    string status=$"progress={app.loadingView.history[^1]} loading={app.isLoadingDirt} viewHidden={app.view.isHidden} loadingVisible={app.loadingView.IsVisibleInTree()} menuVisible={app.mainMenu.IsVisibleInTree()}";
    GD.Print(status); File.WriteAllText(Path.Combine(dir,"loading-state.txt"),status);
    if(DisplayServer.GetName()!="headless") {
     await tree.ToSignal(RenderingServer.Singleton, RenderingServer.SignalName.FramePostDraw);
     tree.Root.GetTexture().GetImage().SavePng(Path.Combine(dir,"loading-at-93.png"));
    }
   }
   await AppController.frame(tree);
  }
  GD.Print($"raceRevealed={!app.isLoadingDirt} sampled={sampled}");
  SceneKit.Foundation.exit(sampled ? 0 : 1);
 }
}

